name: Close Inactive Issues
on:
  schedule:
    - cron: '0 9 * * *'
jobs:
  close_inactive_issues:
    runs-on: ubuntu-latest
    steps:
      - name: Close inactive issues
        uses: actions/github-script@v6
        with:
          script: |
            const days = 90;
            const query = `
              query {
                search(query: "is:issue is:open updated:<${days} days ago", type: ISSUE) {
                  nodes {
                    id
                  }
                }
              }
            `;
            const result = await github.search.searchIssues(query);
            if (result.data.search.nodes.length > 0) {
              result.data.search.nodes.forEach(issue => {
                github.rest.issues.close({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issue.id.split('/')?.[1]),
                });
              });
            }

LLM_YML_Output (codegemma-7b):
name: Close Inactive Issues
on:
  schedule:
    - cron: '0 0 * * *'
jobs:
  close-issues:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/github-script@v6
        with:
          script: |
            const { context } = github;
            const { owner, repo } = context.repo;
            const threshold = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
            const issues = await github.rest.issues.listForRepo({
              owner,
              repo,
              state: 'open',
              created_at: {
                lte: threshold.toISOString(),
              },
            });
            for (const issue of issues.data) {
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: issue.number,
                state: 'closed',
              });
            }

