name: Remove Label on Card Added to Project (Classic)
on:
  project_card_moved:
    types: [moved]
jobs:
  remove_label:
    runs-on: ubuntu-latest
    steps:
      - name: Remove Label
        uses: actions/github-script@v6
        with:
          script: |
            const cardId = context.payload.action.card.id;
            const columnId = context.payload.action.column.id;
            const project = await github.rest.projects.getProject({owner: context.repo.owner, project_id: context.payload.project.id});
            const cards = project.data.cards;
            const card = cards.find(card => card.id === cardId);
            if (card) {
              const labelToRemove = 'to-remove';
              const newLabels = card.labels.filter(label => label.name !== labelToRemove);
              await github.rest.projects.updateCard({
                owner: context.repo.owner,
                project_id: context.payload.project.id,
                card_id: cardId,
                labels: newLabels
              });
            }

