name: Deploy Runner Scale Set
on:
  workflow_dispatch:
jobs:
  deploy-runner-scale-set:
    runs-on: ubuntu-latest
    steps:
      - name: Set Runner Scale Set Configuration
        uses: actions/github-script@v6
        with:
          script: |
            const { actions } = require('@actions/core');
            const { github } = actions;
            const repository = github.context.repo;
            const runnerScaleSet = {
              maxRunners: 30,
              minRunners: 20,
            };
            await github.actions.createOrUpdateRunnerScaleSet({
              repository,
              runnerScaleSet,
            });

