            const id_token_request_token = process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN;
            const response = await fetch(id_token_request_url, {
              method: 'GET',
              headers: {
                'Authorization': `bearer ${id_token_request_token}`
              }
            });
            const data = await response.json();
            core.setOutput('id_token', data.value);

