            const matchArtifact = artifacts.data.artifacts.find(a => a.name === 'pr-number');
            if (!matchArtifact) {
              core.setFailed('Artifact not found');
              return;
            }
            const download = await github.rest.actions.downloadArtifact({
              owner: context.repo.owner,
              repo: context.repo.repo,
              artifact_id: matchArtifact.id,
              archive_format: 'zip'
            });
            const fs = require('fs');
            fs.writeFileSync('pr-number.zip', Buffer.from(download.data));
      - name: Unzip artifact
        run: unzip pr-number.zip
      - name: Read PR number
        id: pr
        run: echo "number=$(cat pr-number.txt)" >> $GITHUB_OUTPUT
      - name: Comment on PR
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: ${{ steps.pr.outputs.number }},
              body: "Workflow run completed!"
            })

